"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[99767],{28453:(e,a,t)=>{t.d(a,{R:()=>r,x:()=>s});var n=t(96540);const i={},l=n.createContext(i);function r(e){const a=n.useContext(l);return n.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function s(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),n.createElement(l.Provider,{value:a},e.children)}},64553:(e,a,t)=>{t.r(a),t.d(a,{assets:()=>o,contentTitle:()=>s,default:()=>c,frontMatter:()=>r,metadata:()=>n,toc:()=>d});const n=JSON.parse('{"id":"qiangguo/americatrouble","title":"","description":"Today, the whole world is buzzing with the news that America has killed Uday and Qusay, but this is merely the agitation stirred up by the news. Even the truth or falsity of the news itself has no real significance. In a sense, America\'s real trouble only truly begins after Saddam, Uday, and Qusay are all killed.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/americatrouble.md","sourceDirName":"qiangguo","slug":"/qiangguo/americatrouble","permalink":"/en/qiangguo/americatrouble","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"americatrouble","title":"","hide_table_of_contents":true,"sidebar_label":"I think America\'s real troubles only began after Saddam, Uday, and Qusay were all killed"},"sidebar":"qiangguoSidebar","previous":{"title":"\u4ec0\u4e48\u53eb\u505a\u4eba\u6c11\u5e01\u7684\u7a0d\u5fae\u5347\u503c\uff1f\u6709\u4e9b\u4e1c\u897f\u662f\u4e0d\u80fd\u7a0d\u5fae\u7684\uff0c\u4f8b\u5982\u5931\u8eab\u548c\u4eba\u6c11\u5e01\u5347\u503c","permalink":"/en/qiangguo/rmbappreciation"},"next":{"title":"\u8d44\u672c\u5168\u7403\u5316\u80cc\u666f\u4e0b\u7684\u5965\u8fd0\u8c0e\u8a00----------\u76ee\u524d\u610f\u4e49\u4e0b\u7684\u5965\u8fd0\u4f1a\u662f\u5426\u5df2\u7ecf\u5230\u4e86\u5bff\u7ec8\u4e4b","permalink":"/en/qiangguo/olympicslies"}}');var i=t(74848),l=t(28453);const r={id:"americatrouble",title:"",hide_table_of_contents:!0,sidebar_label:"I think America's real troubles only began after Saddam, Uday, and Qusay were all killed"},s="I Think America's Real Trouble Only Begins After Saddam, Uday, and Qusay Are All Killed",o={},d=[];function h(e){const a={h1:"h1",header:"header",p:"p",...(0,l.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(a.header,{children:(0,i.jsx)(a.h1,{id:"i-think-americas-real-trouble-only-begins-after-saddam-uday-and-qusay-are-all-killed",children:"I Think America's Real Trouble Only Begins After Saddam, Uday, and Qusay Are All Killed"})}),"\n",(0,i.jsx)(a.p,{children:"Today, the whole world is buzzing with the news that America has killed Uday and Qusay, but this is merely the agitation stirred up by the news. Even the truth or falsity of the news itself has no real significance. In a sense, America's real trouble only truly begins after Saddam, Uday, and Qusay are all killed."}),"\n",(0,i.jsx)(a.p,{children:"\"Killed\" here is meant in the American sense\u2014that is, America announces to the world that Saddam, Uday, and Qusay have all been killed. Once this ultimately happens, America will begin its real trouble. Whether Saddam, Uday, and Qusay are actually killed has no significance whatsoever. For example, even if they were not killed, they couldn't exactly come out and say \"We haven't been killed\"\u2014wouldn't that be insane? And even if they are killed, it wouldn't change anything. Because this is hatred between two nations, between two different cultures, between two peoples of different religious faiths. Hatred is planted in the heart; it has nothing to do with material things."}),"\n",(0,i.jsx)(a.p,{children:'I once wrote a post titled "There is not much time left for America to prevent Iraq from becoming a new Chechnya." Once America announces to the world that Saddam, Uday, and Qusay have all been killed, it will signal the Chechenization of Iraq. America\'s last so-called moral objective will be gone, yet in substance nothing will have changed. Ethnicity, religion, interests, and all the most direct factors will burst forth with renewed force\u2014this is the real trouble.'}),"\n",(0,i.jsx)(a.p,{children:"In that post, I offered an invasion theorem: any occupation not accompanied by large-scale immigration will ultimately fail. Therefore, America's failure is inevitable. The deaths of Saddam, Uday, and Qusay will completely shatter all American-style salvation myths, and then they will face the most raw interests. All mythological justifications will vanish, but American interests will remain, Iraqi interests will remain\u2014these do not depart with Saddam, Uday, and Qusay, but will only become sharper and more direct."}),"\n",(0,i.jsx)(a.p,{children:"From the very beginning, it was destined that what America faced was an enterprise with no victory, and the substance of this enterprise lies in rescuing the dollarization bubble\u2014but that topic is too large, so I'll save it for another time. But it must be stated once again: war is America's only way out of its crisis, and also the best accelerator of America's crisis\u2014a paradox that America cannot escape. In the face of this paradox, what significance does the life or death of Saddam, Uday, and Qusay really hold?"})]})}function c(e={}){const{wrapper:a}={...(0,l.R)(),...e.components};return a?(0,i.jsx)(a,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}}}]);